source('environment/bootstrap.R')
source('meta_analysis/core.R');library(metafor)
count<-0
check<-function(ok,name){if(!isTRUE(ok))stop(paste('FAIL:',name));count<<-count+1;cat('PASS:',name,'\n')}
close<-function(a,b,tol=1e-7)isTRUE(all.equal(as.numeric(a),as.numeric(b),tolerance=tol,check.attributes=FALSE))
reject<-function(f,name)check(inherits(tryCatch({f();NULL},error=function(e)e),'error'),name)
z<-read.csv('examples/synthetic_data/groups.csv');md<-effect_sizes(z)
check(close(md$yi[1],.7)&&close(md$vi[1],(1.8^2+2.1^2)/18),'MD hand-calculated reference')
sem<-z;sem$error_t<-z$error_t/sqrt(z$n_t);sem$error_c<-z$error_c/sqrt(z$n_c);sem$error_type_t<-'SEM';sem$error_type_c<-'SEM';s<-effect_sizes(sem);check(close(s$yi,md$yi)&&close(s$vi,md$vi),'SEM conversion')
g<-effect_sizes(z,'Hedges_g');df<-34;sp<-sqrt((17*1.8^2+17*2.1^2)/34);expected<-(1-3/135)*.7/sp
check(close(g$yi[1],expected)&&close(g$vi[1],1/18+1/18+expected^2/68),'Hedges approximate-J df variance independent reference')
gx<-effect_sizes(z,'Hedges_g',g_correction='exact',g_variance='LS');ref<-escalc(measure='SMD',m1i=z$mean_t,m2i=z$mean_c,sd1i=z$error_t,sd2i=z$error_c,n1i=z$n_t,n2i=z$n_c,vtype='LS');check(close(gx$yi,ref$yi)&&close(gx$vi,ref$vi),'Exact-J LS alternative versus metafor escalc')
for(method in c('REML','PM','DL')){
 a<-fit_meta(md,method);m<-rma.uni(yi=md$yi,vi=md$vi,method=method,test='knha',control=list(threshold=1e-10,tol=1e-12,maxiter=10000))
 check(close(c(a$estimate,a$tau2,a$HK_SE,a$CI,a$p),c(m$b,m$tau2,m$se,m$ci.lb,m$ci.ub,m$pval),1e-6),paste(method,'independent metafor inference'))
 check(close(a$Q,m$QE)&&close(a$I2,max(0,1-(nrow(md)-1)/m$QE)*100),paste(method,'Q and Q-based I2'))
 check(close(a$PI,as.numeric(m$b)+c(-1,1)*qt(.975,nrow(md)-2)*sqrt(m$tau2+m$se^2)),paste(method,'independent Riley PI calculation'))
 check(close(sum(a$weights),100)&&a$df==nrow(md)-1&&a$PI_df==nrow(md)-2,paste(method,'weights and dfs'))
}
e<-data.frame(id=paste0('Tiny',1:4),independence_id=paste0('Tiny_cohort',1:4),independent=TRUE,yi=c(.10,.11,.12,.13),vi=rep(1,4));a<-fit_meta(e);check(a$HK_q<1&&a$HK_variance<1/4,'Unmodified HKSJ has no max(1,q) floor')
a<-fit_meta(md[1:2,]);check(all(is.na(a$PI))&&is.na(a$PI_df)&&a$df==1,'k2 no PI')
a<-fit_meta(md[1,,drop=FALSE]);check(a$k==1&&all(is.na(a$CI))&&all(is.na(a$PI)),'k1 no pooled inference')
zero<-e;zero$yi<-rep(0,4);a<-fit_meta(zero);check(a$HK_SE==0&&is.na(a$p)&&a$status=='ZERO_RESIDUAL_HK_INFERENCE_DEGENERATE','Zero-residual inference flagged')
out<-run_specifications(md,config=list(subsets=list(list(name='low',where=list(list(field='risk',operator='ne',value='HIGH'))))));check(length(out$leave_one_out)==nrow(md)&&out$custom$low$k==5,'LOO and conditional sensitivity')
for(i in seq_len(nrow(md))){m<-rma.uni(yi=md$yi[-i],vi=md$vi[-i],method='REML',test='knha',control=list(threshold=1e-10,tol=1e-12,maxiter=10000));check(close(out$leave_one_out[[i]]$estimate,m$b),paste('Independent LOO',i))}
bad<-z;bad$n_t[1]<-NA;reject(function()effect_sizes(bad),'Missing N rejected')
bad<-z;bad$error_t[1]<--1;reject(function()effect_sizes(bad),'Negative SD rejected')
bad<-z;bad$error_type_t[1]<-'NR';reject(function()effect_sizes(bad),'Unknown variance type rejected')
bad<-z;bad$unit[1]<-'other_units';reject(function()effect_sizes(bad),'MD unit conflict rejected')
bad<-z;bad$independence_id[2]<-bad$independence_id[1];reject(function()effect_sizes(bad),'Dependent cohort rejected')
bad<-z;bad$shared_control[1]<-TRUE;reject(function()effect_sizes(bad),'Shared controls rejected')
bad<-z;bad$control_id[2]<-bad$control_id[1];reject(function()effect_sizes(bad),'Repeated control id rejected')
bad<-md;bad$vi[1]<-0;reject(function()fit_meta(bad),'Zero effect variance rejected')
bad<-md;bad$yi[1]<-Inf;reject(function()fit_meta(bad),'Nonfinite effect rejected')
reject(function()fit_meta(md[0,]),'Empty input rejected')
es<-read.csv('examples/synthetic_data/effects.csv');es$se<-sqrt(es$vi);check(close(effect_sizes(es,input_type='effects')$vi,es$vi),'Effects variance or SE input')
es$se[1]<-9;reject(function()effect_sizes(es,input_type='effects'),'Conflicting variance and SE rejected')
reject(function()select_rows(md,list(list(field='risk',operator='execute',value='x'))),'No executable filter strings')
reject(function()fit_meta(md,'ML'),'Unsupported estimator rejected')
bad<-md;bad$yi[1]<-1e200;reject(function()fit_meta(bad),'Numerical overflow risk rejected')
bad<-md;bad$yi[1]<-50;a<-fit_meta(bad);check(a$k==nrow(bad)&&is.finite(a$estimate),'Finite extreme effect retained rather than silently excluded')
bad<-es;bad$se<-NULL;bad$n_t<-c(-2,rep(10,4));bad$n_c<-rep(10,5);reject(function()effect_sizes(bad,input_type='effects'),'Invalid supplied effect-input N rejected')
dir.create('outputs/tests',recursive=TRUE,showWarnings=FALSE)
jsonlite::write_json(list(PASS=TRUE,checks=count,reference='metafor plus independent hand calculations'), 'outputs/tests/meta_test_summary.json',auto_unbox=TRUE,pretty=TRUE)
cat('META_TEST_CHECKS=',count,'\n')
